  [9884] = { "$D1の間、味方の対象のアーマーを$N1、すべての能力値を$N2、すべての抵抗力を$N3上げます。", "アーマーが$N1、すべての能力値が$N2、すべての耐性が$N3上昇します。", 0x48c4c0cd, 0xa07843b3, "uu" },
  [9885] = { "$D1の間、味方の対象のアーマーを$N1、すべての能力値を$N2、すべての抵抗力を$N3上げます。", "アーマーが$N1、すべての能力値が$N2、すべての耐性が$N3上昇します。", 0x48c4c0cd, 0xa07843b3, "uu" },
  [9888] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [9889] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [9892] = { "身をすくめます。ダメージは与えませんが脅威が大きく下がり、敵に攻撃されにくくなります。", nil, 0x34d148da, nil, "um" },
  [9894] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはコンボポイントごと、およびAttack Powerによって増加します：\n $N1ポイント：$D1かけて$N2のダメージ。\n $N4ポイント：$D2かけて$N5のダメージ。\n $N7ポイント：$D3かけて$N8のダメージ。\n $N10ポイント：$D4かけて$N11のダメージ。\n $N13ポイント：$D5かけて$N14のダメージ。", "$N2秒ごとに$N1の出血ダメージを受けます。", 0x49157ab0, 0x75c83da5, "uu" },
  [9896] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはコンボポイントごと、およびAttack Powerによって増加します：\n $N1ポイント：$D1かけて$N2のダメージ。\n $N4ポイント：$D2かけて$N5のダメージ。\n $N7ポイント：$D3かけて$N8のダメージ。\n $N10ポイント：$D4かけて$N11のダメージ。\n $N13ポイント：$D5かけて$N14のダメージ。", "$N2秒ごとに$N1の出血ダメージを受けます。", 0x49157ab0, 0x75c83da5, "uu" },
  [9898] = { "ドルイドが咆哮し、近くの敵の近接攻撃力を$N1下げます。効果時間は$D1です。", "近接攻撃力が$N1低下しています。", 0x79835d42, 0x5069052b, "uu" },
  [9900] = { "30分間、鋭い武器のダメージを6上げます。", nil, 0x31fba5f6, nil, "um" },
  [9901] = { "対象の獣をなだめ、あなたを攻撃してくる距離を$N1ヤード縮めます。レベル70以下のBeastにのみ有効です。効果時間は$D1です。", "目標が攻撃してくる距離が短くなります。", 0x92f8f398, 0x6f0854bf, "uu" },
  [9903] = { "30分間、鈍器のダメージを6上げます。", nil, 0xa989ce00, nil, "um" },
  [9904] = { "対象を引き裂き、$N1のダメージと、$D1かけてさらに$N2のダメージを与えます。コンボポイントを$N4獲得します。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0x59b5d40d, 0x84eecd00, "uu" },
  [9907] = { "$D1の間、対象のアーマーを$N1減少させます。効果中、対象はステルスや透明化ができません。", "アーマーが$N1低下します。ステルスも透明化もできません。", 0xf183631b, 0xa06fedc8, "uu" },
  [9908] = { "近くの敵$N1体をなぎ払い、$N2のダメージを与えます。", nil, 0xb0c704b4, nil, "um" },
  [9910] = { "味方の対象から棘が生え、攻撃してきた相手に$N1のNatureダメージを与えます。効果時間は$D1です。", "攻撃者に$N1のNatureダメージを与えます。", 0x0eddc25a, 0x763a853a, "uu" },
  [9912] = { "対象に$N1のNatureダメージを与えます。", nil, 0xb57329ad, nil, "um" },
  [9913] = { "ドルイドが忍び歩きできるようになりますが、移動速度が$N1%低下します。解除するまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0x17709e32, 0x2854da84, "uu" },
  [9918] = { "1時間6で武器のダメージを増加させるには、刃の武器をシャープにします。レベル200以上の項目に適用することはできません。", nil, 0xbc40f7e3, nil, "um" },
  [9921] = { "1時間6で武器のダメージを増加させるには、鈍器のバランスをとります。レベル200以上の項目に適用することはできません。", nil, 0x77c8a0aa, nil, "um" },
  [9939] = { "あなたがそれをブロックするたびにダメージを盾にミスリルのスパイクをアタッチします。", nil, 0x7c4fbcde, nil, "um" },
  [9964] = { "4％、マウントされた移動速度を増加させるあなたのブーツに拍車をアタッチします。この利点を得るために、レベルが70以下でなければなりません。", nil, 0x894bd612, nil, "um" },
  [9976] = { "オウムはクラッカーが大好き！", nil, 0x2582a57d, nil, "um" },
  [9979] = { "既存の固定化の効果を削除して、5秒間固定化の効果には免疫ができます。", nil, 0x97fd565d, nil, "um" },
})
